#[derive(PartialEq,Eq)] pub struct ListNode{pub val:i32,pub next:Option<Rc<RefCell<ListNode>>>}
use std::{rc::Rc,cell::RefCell};impl Solution{pub fn get_intersection_node(a:Option<Rc<RefCell<ListNode>>>,b:Option<Rc<RefCell<ListNode>>>)->Option<Rc<RefCell<ListNode>>>{let(mut x,mut y)=(a.clone(),b.clone());while !Self::same(&x,&y){x=match x{Some(n)=>n.borrow().next.clone().or(b.clone()),None=>b.clone()};y=match y{Some(n)=>n.borrow().next.clone().or(a.clone()),None=>a.clone()}}x}fn same(a:&Option<Rc<RefCell<ListNode>>>,b:&Option<Rc<RefCell<ListNode>>>)->bool{match(a,b){(Some(x),Some(y))=>Rc::ptr_eq(x,y),(None,None)=>true,_=>false}}}
